/* gesummv.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

#ifdef _OPENMP
#include <omp.h>
#endif

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "gesummv.h"

/* --------------------------------------------------------------------
 * Tunable parameters for the optimized kernel.
 *
 * GESUMMV_J_BLOCK_SIZE:
 *   - Block size used to tile the inner (j) loop.
 *   - Must be a positive integer.
 *   - Can be overridden at compile time, e.g.:
 *       -DGESUMMV_J_BLOCK_SIZE=128
 *
 * GESUMMV_OMP_MIN_N:
 *   - Minimum problem size to enable OpenMP parallelization
 *     of the outer (i) loop.
 *   - Can be overridden at compile time, e.g.:
 *       -DGESUMMV_OMP_MIN_N=1024
 * ------------------------------------------------------------------ */
#ifndef GESUMMV_J_BLOCK_SIZE
#define GESUMMV_J_BLOCK_SIZE 64
#endif

#ifndef GESUMMV_OMP_MIN_N
#define GESUMMV_OMP_MIN_N 256
#endif


/* Array initialization. */
static
void init_array(int n,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(B,N,N,n,n),
		DATA_TYPE POLYBENCH_1D(x,N,n))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < n; i++)
    {
      x[i] = (DATA_TYPE)( i % n) / n;
      for (j = 0; j < n; j++) {
	A[i][j] = (DATA_TYPE) ((i*j+1) % n) / n;
	B[i][j] = (DATA_TYPE) ((i*j+2) % n) / n;
      }
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(y,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("y");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, y[i]);
  }
  POLYBENCH_DUMP_END("y");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_gesummv[[gnu::flatten, gnu::noinline]](int n,
		    DATA_TYPE alpha,
		    DATA_TYPE beta,
		    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		    DATA_TYPE POLYBENCH_2D(B,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(tmp,N,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(y,N,n))
{
  /* Provide the compiler with additional aliasing information.
   *
   * The original PolyBench code allocates A, B, tmp, x, and y as
   * distinct arrays. Creating local 'restrict' aliases allows the
   * optimizer to safely vectorize and reorder memory accesses without
   * assuming pointer aliasing between these arrays.
   */
  DATA_TYPE (*restrict A_)[n] = A;
  DATA_TYPE (*restrict B_)[n] = B;
  DATA_TYPE *restrict tmp_    = tmp;
  const DATA_TYPE *restrict x_ = x;
  DATA_TYPE *restrict y_      = y;

  /* Use the PolyBench loop bound macro exactly once and store it in a
   * local variable; this preserves the original semantics while making
   * the value available to OpenMP and for minor loop optimizations.
   */
  const int n_pb = _PB_N;

  /* Tiling factor for the inner (j) loop. This is a compile-time
   * constant that can be tuned through GESUMMV_J_BLOCK_SIZE.
   */
  const int j_block = GESUMMV_J_BLOCK_SIZE;

  /* The computation performed here is:
   *   tmp[i] = Σ_j A[i][j] * x[j]
   *   y[i]   = α * tmp[i] + β * Σ_j B[i][j] * x[j]
   *
   * The optimized version keeps the partial sums in registers
   * (sumA, sumB) instead of writing back to tmp[i] and y[i] at each
   * inner-loop iteration. We write the final values to tmp[i] and y[i]
   * only once per row, which reduces memory traffic while preserving
   * the exact sequence of floating-point operations within the inner
   * loop (same recurrence pattern).
   */

#pragma scop
  /* Parallelize across rows when OpenMP is enabled. Each iteration of
   * the outer loop touches a distinct row of A and B and writes
   * disjoint elements of tmp and y, so there are no cross-iteration
   * dependencies.
   *
   * The 'if' clause avoids creating threads for very small problems.
   */
#ifdef _OPENMP
#pragma omp parallel for schedule(static) if (n_pb >= GESUMMV_OMP_MIN_N)
#endif
  for (int i = 0; i < n_pb; i++)
    {
      /* Row-wise accumulators kept in registers. */
      DATA_TYPE sumA = SCALAR_VAL(0.0);
      DATA_TYPE sumB = SCALAR_VAL(0.0);

      /* Pointers to the i-th row of A and B. These are contiguous in
       * memory along the j dimension, which is ideal for vectorization.
       */
      DATA_TYPE *restrict Ai = A_[i];
      DATA_TYPE *restrict Bi = B_[i];

      /* Tile the inner j loop in blocks of size j_block. This does not
       * change the order of floating-point operations within each row,
       * but introduces an extra level of looping that can be used to
       * tune cache behavior via GESUMMV_J_BLOCK_SIZE.
       */
      for (int jj = 0; jj < n_pb; jj += j_block)
	{
	  const int j_end = (jj + j_block < n_pb) ? (jj + j_block) : n_pb;

	  /* Tell GCC that there are no loop-carried dependencies that
	   * would inhibit vectorization. The 'restrict' qualifiers
	   * above and the purely accumulative nature of sumA/sumB make
	   * this safe.
	   */
#pragma GCC ivdep
	  for (int j = jj; j < j_end; j++)
	    {
	      const DATA_TYPE xj = x_[j];
	      sumA += Ai[j] * xj;
	      sumB += Bi[j] * xj;
	    }
	}

      /* Store the final results back to memory once per row. This
       * preserves the original observable behavior:
       *   - tmp[i] holds Σ_j A[i][j]*x[j]
       *   - y[i] holds α*tmp[i] + β*Σ_j B[i][j]*x[j]
       */
      tmp_[i] = sumA;
      y_[i]   = alpha * sumA + beta * sumB;
    }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(tmp, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, &alpha, &beta,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B),
	      POLYBENCH_ARRAY(x));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_gesummv (n, alpha, beta,
		  POLYBENCH_ARRAY(A),
		  POLYBENCH_ARRAY(B),
		  POLYBENCH_ARRAY(tmp),
		  POLYBENCH_ARRAY(x),
		  POLYBENCH_ARRAY(y));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(y)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);
  POLYBENCH_FREE_ARRAY(tmp);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(y);

  return 0;
}
