/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(y,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("y");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, y[i]);
  }
  POLYBENCH_DUMP_END("y");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_gesummv[[gnu::flatten, gnu::noinline]](int n,
		    DATA_TYPE alpha,
		    DATA_TYPE beta,
		    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		    DATA_TYPE POLYBENCH_2D(B,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(tmp,N,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j;

  /* Create local 'restrict'-qualified aliases for the PolyBench arrays.
     The benchmark allocates each array in disjoint memory, so this
     non-aliasing assumption is valid for this program and enables
     better vectorization and optimization by the compiler. */
  DATA_TYPE (* restrict A_)[n] = A;
  DATA_TYPE (* restrict B_)[n] = B;
  DATA_TYPE * restrict tmp_    = tmp;
  DATA_TYPE * restrict x_      = x;
  DATA_TYPE * restrict y_      = y;

  const int pb_n = _PB_N;

#pragma scop
  /* Parallelize over rows. Each iteration only reads from A_, B_, x_
     and writes to distinct tmp_[i] and y_[i], so there are no
     cross-iteration dependencies.  When compiled without OpenMP
     support, these pragmas are ignored and the code runs serially. */
#pragma omp parallel for private(j) schedule(static)
  for (i = 0; i < pb_n; i++)
    {
      /* Use scalar accumulators instead of repeatedly updating
         tmp[i] and y[i] in memory. This greatly reduces memory
         traffic and improves cache locality, while preserving the
         original floating-point evaluation order within the inner
         loop. */
      DATA_TYPE sumA = SCALAR_VAL(0.0);
      DATA_TYPE sumB = SCALAR_VAL(0.0);

      DATA_TYPE * restrict Ai = A_[i];
      DATA_TYPE * restrict Bi = B_[i];

      /* Inner loop: row-wise dot products for A and B with x.
         The 'omp simd' directive (ignored if OpenMP SIMD support is
         disabled) tells the compiler that iterations are independent
         and safe to vectorize, while the scalar reductions keep the
         exact accumulation order. */
#pragma omp simd reduction(+:sumA,sumB)
      for (j = 0; j < pb_n; j++)
	{
	  DATA_TYPE xj = x_[j];
	  sumA += Ai[j] * xj;
	  sumB += Bi[j] * xj;
	}

      /* Store the accumulated result for tmp exactly as in the
         original algorithm: tmp[i] holds the dot product of the
         i-th row of A with x. */
      tmp_[i] = sumA;

      /* Final combination:
           y[i] = alpha * tmp[i] + beta * y[i]
         where tmp[i] == sumA and y[i] == sumB at this point.
         We spell this out in two steps to closely match the original
         sequence of floating-point operations. */
      DATA_TYPE scaled_tmp = alpha * sumA;
      DATA_TYPE scaled_y   = beta  * sumB;
      y_[i] = scaled_tmp + scaled_y;
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(tmp, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, &alpha, &beta,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B),
	      POLYBENCH_ARRAY(x));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_gesummv (n, alpha, beta,
		  POLYBENCH_ARRAY(A),
		  POLYBENCH_ARRAY(B),
		  POLYBENCH_ARRAY(tmp),
		  POLYBENCH_ARRAY(x),
		  POLYBENCH_ARRAY(y));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
