  }
  POLYBENCH_DUMP_END("y");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Optimizations applied vs. the reference version:
 *   - Use local accumulators (sumA, sumB) to keep dot products in
 *     registers and perform only one store per output element.
 *   - Introduce restrict-qualified base pointers (tmp_ptr, y_ptr,
 *     x_ptr, A_row, B_row) to improve alias analysis and enable
 *     more aggressive vectorization.
 *   - Add an OpenMP parallel-for over the outer loop (rows of A/B)
 *     guarded by a tunable size threshold.
 *   - Add a GCC ivdep pragma on the inner loop to explicitly state
 *     there are no loop-carried dependencies, which helps vectorizers.
 *
 * All transformations preserve the mathematical result of y and tmp.
 */
static
void kernel_gesummv[[gnu::flatten, gnu::noinline]](int n,
		    DATA_TYPE alpha,
		    DATA_TYPE beta,
		    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		    DATA_TYPE POLYBENCH_2D(B,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(tmp,N,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j;

  /* Local copy of the (possibly instrumented) problem size. */
  const int nPB = _PB_N;

  /* Local copies of scalars; easier for the compiler to keep in registers. */
  const DATA_TYPE alpha_local = alpha;
  const DATA_TYPE beta_local  = beta;

  /* Restrict-qualified base pointers to improve alias analysis.
   * These pointers are the only ones used to access the underlying
   * arrays inside the computational region.
   */
  DATA_TYPE *restrict const tmp_ptr = tmp;
  DATA_TYPE *restrict const y_ptr   = y;
  DATA_TYPE *restrict const x_ptr   = x;

#pragma scop
  /* Parallelize across rows of A and B.  Each iteration i:
   *   - Reads A[i][:], B[i][:], x[:]
   *   - Writes tmp[i], y[i]
   * so there are no cross-iteration dependences.
   *
   * The 'if' clause avoids creating a parallel region for small sizes.
   * When compiled without OpenMP, this pragma is not seen
   * (guarded by _OPENMP) and the loop executes serially.
   */
#if defined(_OPENMP)
# pragma omp parallel for schedule(static) if (nPB >= GESUMMV_OMP_MIN_N) private(j)
#endif
  for (i = 0; i < nPB; i++)
    {
      /* Row pointers for A and B.  Each row is independent, and A_row
       * / B_row never alias any other array.
       */
      DATA_TYPE *restrict A_row = A[i];
      DATA_TYPE *restrict B_row = B[i];

      /* Register accumulators for the two dot products:
       *   sumA = A[i][:] . x[:]
       *   sumB = B[i][:] . x[:]
       */
      DATA_TYPE sumA = SCALAR_VAL(0.0);
      DATA_TYPE sumB = SCALAR_VAL(0.0);

      /* Inner loop: fully dense, unit-stride access to A_row, B_row,
       * and x_ptr. No loop-carried dependences, so it is safe to
       * vectorize.  The GCC ivdep pragma explicitly states this to
       * the compiler.
       */
#pragma GCC ivdep
      for (j = 0; j < nPB; j++)
	{
	  const DATA_TYPE xj = x_ptr[j];
	  sumA += A_row[j] * xj;
	  sumB += B_row[j] * xj;
	}

      /* Store final results once per row.  In the original version,
       * tmp[i] and y[i] were updated at every inner-loop iteration;
       * keeping them in registers and storing once reduces memory
       * traffic while yielding the same final values.
       */
      tmp_ptr[i] = sumA;
      y_ptr[i]   = alpha_local * sumA + beta_local * sumB;
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(tmp, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, &alpha, &beta,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B),
	      POLYBENCH_ARRAY(x));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_gesummv (n, alpha, beta,
		  POLYBENCH_ARRAY(A),
		  POLYBENCH_ARRAY(B),
		  POLYBENCH_ARRAY(tmp),
		  POLYBENCH_ARRAY(x),
		  POLYBENCH_ARRAY(y));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(y)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);
  POLYBENCH_FREE_ARRAY(tmp);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(y);

  return 0;
}
