   - Add OpenMP parallelism on the outer loop and OpenMP SIMD hint on the
     inner loop; when compiled without -fopenmp these pragmas are ignored.
   - Preserve the original floating-point operation order for each sum so
     that numerical results are bitwise identical to the original code,
     except for harmless changes due to register vs. memory storage.

   The mathematical computation is unchanged:
     tmp[i] = sum_j A[i][j] * x[j]
     y[i]   = alpha * tmp[i] + beta * sum_j B[i][j] * x[j]
*/
static void __attribute__((noinline))
kernel_gesummv(int n,
		    DATA_TYPE alpha,
		    DATA_TYPE beta,
		    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		    DATA_TYPE POLYBENCH_2D(B,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(tmp,N,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(y,N,n))
{
