  /* Local aliases with restrict to enable better vectorization.
     Polybench allocates A, B, x, y, tmp as disjoint buffers, so this is safe. */
  DATA_TYPE * __restrict tmp_ = tmp;
  DATA_TYPE * __restrict x_   = x;
  DATA_TYPE * __restrict y_   = y;

  const int nPB = _PB_N;

#pragma scop
  /* Parallelize over rows. Each i-iteration is independent. */
  #pragma omp parallel for private(i, j) schedule(static)
  for (i = 0; i < nPB; i++)
    {
      /* Row pointers for faster access and to give the compiler
         additional aliasing information. */
      DATA_TYPE * __restrict Ai = &A[i][0];
      DATA_TYPE * __restrict Bi = &B[i][0];

      /* Accumulators kept in registers for the whole inner loop. */
      DATA_TYPE accA = SCALAR_VAL(0.0);
      DATA_TYPE accB = SCALAR_VAL(0.0);

      /* Inner dot products over row i of A and B with vector x.
