	  accB += Bi[j] * xj;  /* corresponds to: y[i]   = B[i][j]*x[j] + y[i];   */
	}

      /* Write back the temporary result and final y value. */
      tmp_[i] = accA;
      y_[i]   = alpha * accA + beta * accB;
    }
#pragma endscop

